<div class="page-heading"><div><p class="eyebrow">TIM YANG MENJAGA KAFE</p><h1>Akun pengguna</h1><p class="page-subtitle">Satu akun untuk setiap orang, dengan akses sesuai perannya.</p></div><a class="button button-primary" href="<?=e(url('users'))?>#userForm">＋ <span>Tambah akun</span></a></div><section class="panel"><div class="panel-head"><div><h2>Anggota tim</h2><p><?=count($data['users'])?> akun terdaftar</p></div></div><div class="table-scroll"><table><thead><tr><th>Nama</th><th>Username</th><th>Email</th><th>Peran</th><th>Status</th><th>Bergabung</th><th></th></tr></thead><tbody><?php foreach($data['users'] as $u):?><tr><td><strong><?=e($u['full_name'])?></strong></td><td class="invoice-cell"><?=e($u['username'])?></td><td><?=e($u['email'])?></td><td><?=e(ucfirst($u['role']))?></td><td><span class="status <?=$u['status']==='active'?'status-completed':'status-cancelled'?>"><?=e(ucfirst($u['status']))?></span></td><td><?=e(date_id($u['created_at']))?></td><td><a class="row-link" href="<?=e(url('users',['edit'=>$u['id']]))?>#userForm">Ubah</a></td></tr><?php endforeach?></tbody></table></div></section><section class="panel user-editor" id="userForm"><div class="panel-head"><div><h2><?=$data['edit']?'Ubah akun':'Akun baru'?></h2><p>Password minimal 8 karakter dan akan disimpan dengan hash.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_user"><input type="hidden" name="id" value="<?=e($data['edit']['id']??0)?>"><label>Nama lengkap<input name="full_name" value="<?=e($data['edit']['full_name']??'')?>" required></label><label>Username<input name="username" value="<?=e($data['edit']['username']??'')?>" required></label><label>Email<input name="email" type="email" value="<?=e($data['edit']['email']??'')?>" required></label><label>Peran<select name="role"><?php foreach(['cashier'=>'Kasir','waiter'=>'Pelayan','manager'=>'Manager','admin'=>'Administrator'] as $role=>$label):?><option value="<?=$role?>" <?=($data['edit']['role']??'cashier')===$role?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>Password <?=$data['edit']?'<small>Opsional, kosongkan agar tidak berubah</small>':''?><input name="password" type="password" minlength="8" <?=$data['edit']?'':'required'?>></label><?php if($data['edit']):?><label class="check-line"><input type="checkbox" name="active" <?=$data['edit']['status']==='active'?'checked':''?>> Akun aktif</label><?php endif?><div class="form-actions"><button class="button button-primary"><?=$data['edit']?'Simpan perubahan':'Simpan akun'?></button></div></form></section>
